-- Sample Chart of Accounts data for fims.chart_of_accounts
-- Sourced from the 2019 Revised Chart of Accounts for National Government Agencies
-- (Philippine UACS/PPSAS GL codes), pasted by the user as sample data.
--
-- Notes on how this was generated (parse_coa.js, run once to produce this file):
--  - account_id is a synthetic sequential surrogate key (COA-00001, COA-00002, ...)
--    assigned in source order; account_code is the real UACS code and is the
--    natural/unique business key.
--  - account_type is DERIVED from the leading digit of account_code
--    (1=Asset, 2=Liability, 3=Equity, 4=Revenue, 5=Expense) rather than the
--    account_type values in the pasted source, which drifted inconsistent
--    partway through (e.g. the Inventories branch and part of Other Receivables
--    were labeled Liability/Equity despite being 1-xx Asset codes).
--  - parent_account_id is resolved from the UACS code hierarchy itself
--    (dropping one '-' separated segment at a time), normalizing away the
--    inconsistent leading-zero padding on the first segment (e.g. "01-01" and
--    "1-01" are the same node).
--  - Region / Project / Acctg Book columns from the pasted sheet were not
--    carried over: they were blank on every row except one ("Acctg Book" =
--    ACCT-001 on the very first summary row only), and per the existing
--    design note (see project_coa_book_selector memory) accounts are meant to
--    be book-agnostic, so no column for this was added.
--  - posting_allowed is true only where the source explicitly said "Yes";
--    status defaults to 'Active' for all rows (no Inactive rows were present
--    in the source); source_document is set to 'Accounting COA (sample)' only
--    where the source explicitly carried that value.
--  - Two malformed rows from the source were dropped as transcription
--    artifacts (duplicate codes with garbage titles: "02-01-04 / 10" and
--    "05-05-04 / Change").

-- NOTE: "02 - sample_data/03 - fims_chart_of_accounts.sql" seeds the full COA
-- (same account_codes, different account_ids). This sample set only loads into
-- an EMPTY table so the two seeds never collide on account_code.
INSERT INTO fims.chart_of_accounts (
    account_id, account_code, account_title, account_type,
    parent_account_id, posting_allowed, status, source_document
)
